import{_ as o,W as p,s as d,u,ah as i,I as s,w as a,Z as n,A as l}from"./chunks/framework.ChbOY6p5.js";import"./chunks/theme.B6FFP-dx.js";const k=JSON.parse('{"title":"如何在 Linux 中实时监控日志文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中实时监控日志文件 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Linux 中实时监控日志文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中实时监控日志文件 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220814 How to Monitor Log Files in Real Time in Linux [Desktop and Server]","title":"如何在 Linux 中实时监控日志文件","tag":"202208"},"relativePath":"202208/20220814 How to Monitor Log Files in Real Time in Linux [Desktop and Server].md","filePath":"[post].md"}'),r={name:"202208/20220814 How to Monitor Log Files in Real Time in Linux [Desktop and Server].md"};function g(m,t,h,c,v,b){const e=p("Link");return u(),d("div",null,[t[21]||(t[21]=i('<h1 id="如何在-linux-中实时监控日志文件" tabindex="-1">如何在 Linux 中实时监控日志文件 <a class="header-anchor" href="#如何在-linux-中实时监控日志文件" aria-label="Permalink to 如何在 Linux 中实时监控日志文件">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202208/19/194609f1njqu096uhy919i.jpg" alt=""></p><blockquote><p>本教程介绍了如何实时监控 Linux 日志文件（桌面、服务器或应用）以进行诊断和故障排除。</p></blockquote><p>当你在 Linux 桌面、服务器或任何应用中遇到问题时，你首先会查看单独的日志文件。日志文件通常是文本流和来自应用的带有时间戳的消息。它可以帮助你缩小特定问题的范围，并使你能够找到问题的原因。它还可以帮助从网络获得帮助。</p><p>一般来说，所有的日志文件都位于 <code>/var/log</code>。此目录包含特定应用和服务的扩展名为 <code>.log</code> 的日志文件，它还包含了其他含有日志的独立目录。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/log-files-in-var-log-1024x312.jpeg" alt="log files in var-log"></p><p>所以，如果你想监控一堆日志文件或特定的一个，这里有一些方法可以做到。</p><h3 id="linux-实时监控日志文件" tabindex="-1">Linux 实时监控日志文件 <a class="header-anchor" href="#linux-实时监控日志文件" aria-label="Permalink to Linux 实时监控日志文件">​</a></h3><h4 id="使用-tail-命令" tabindex="-1">使用 tail 命令 <a class="header-anchor" href="#使用-tail-命令" aria-label="Permalink to 使用 tail 命令">​</a></h4><p><code>tail</code> 命令是实时跟踪日志文件的最基本方式。特别是如果你在只有终端而没有 GUI 的服务器中。这很有帮助。</p><p>基本语法如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tail /path/to/log/file</span></span></code></pre></div><p>用法：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/Monitoring-multiple-log-files-via-tail.jpeg" alt="Monitoring multiple log files via tail"></p><p>可以使用开关 <code>-f</code> 跟踪实时更新的日志文件。例如，如果要关注 syslog，可以使用以下命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tail -f /var/log/syslog</span></span></code></pre></div><p>你可以使用单个命令监控多个日志文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tail -f /var/log/syslog /var/log/dmesg</span></span></code></pre></div><p>如果要监视 HTTP 或 sftp 或任何服务器，可以在此命令中使用它们各自的日志文件。</p><p>请记住，上述命令需要管理员权限。</p><h4 id="使用-lnav-日志文件浏览器" tabindex="-1">使用 lnav（日志文件浏览器） <a class="header-anchor" href="#使用-lnav-日志文件浏览器" aria-label="Permalink to 使用 lnav（日志文件浏览器）">​</a></h4><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/08/lnav-Running.jpeg" alt="lnav Running"></p><p><code>lnav</code> 是一个出色的程序，你可以用它来用彩色编码的信息以更有条理的方式监控日志文件。在 Linux 系统中，这个工具不是默认安装的。你可以用下面的命令来安装它：</p><p>Ubuntu：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install lnav</span></span></code></pre></div><p>Fedora：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo dnf install lnav</span></span></code></pre></div>',27)),s("p",null,[t[1]||(t[1]=a("lnav 的好处在于，如果你不想安装它，你可以下载其预编译的可执行文件并在任何地方运行它，甚至可以从 U 盘上运行。无需设置，并加载了功能。使用 lnav，你可以通过 SQL 查询日志文件，以及其他很酷的功能，你可以在其")),n(e,{href:"https://lnav.org/features"},{default:l(()=>t[0]||(t[0]=[a("官方网站")])),_:1}),t[2]||(t[2]=a("上学习。"))]),t[22]||(t[22]=i(`<p>安装后，你可以在具有管理员权限的终端上运行 <code>lnav</code>，它会默认显示 <code>/var/log</code> 中的所有日志并开始实时监控。</p><h4 id="关于-systemd-的-journalctl-的一个说明" tabindex="-1">关于 systemd 的 journalctl 的一个说明 <a class="header-anchor" href="#关于-systemd-的-journalctl-的一个说明" aria-label="Permalink to 关于 systemd 的 journalctl 的一个说明">​</a></h4><p>当今所有现代 Linux 发行版都主要使用 systemd。 systemd 提供了运行 Linux 操作系统的基本框架和组件。 systemd 通过 <code>journalctl</code> 提供日志服务，这有助于管理来自所有 systemd 服务的日志。你还可以使用以下命令实时监控各个 systemd 服务和日志。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>journalctl -f</span></span></code></pre></div><p>以下是一些特定的 <code>journalctl</code> 命令，可用于多种情况。你可以将这些与上面的 <code>-f</code> 选项结合使用以开始实时监控。</p><p>对于紧急系统消息，请使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>journalctl -p 0</span></span></code></pre></div><p>显示带有解释的错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>journalctl -xb -p 3</span></span></code></pre></div><p>使用时间控制过滤：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>journalctl --since &quot;2022-12-04 06:00:00&quot;</span></span>
<span class="line"><span>journalctl --since &quot;2022-12-03&quot; --until &quot;2022-12-05 03:00:00&quot;</span></span>
<span class="line"><span>journalctl --since yesterday</span></span>
<span class="line"><span>journalctl --since 09:00 --until &quot;1 hour ago&quot;</span></span></code></pre></div>`,11)),s("p",null,[t[4]||(t[4]=a("如果你想了解更多关于 journalctl 的详细信息，我已经在这写了份 ")),n(e,{href:"https://www.debugpoint.com/2020/12/systemd-journalctl/"},{default:l(()=>t[3]||(t[3]=[a("指南")])),_:1}),t[5]||(t[5]=a("。"))]),t[23]||(t[23]=s("h3",{id:"结束语",tabindex:"-1"},[a("结束语 "),s("a",{class:"header-anchor",href:"#结束语","aria-label":"Permalink to 结束语"},"​")],-1)),t[24]||(t[24]=s("p",null,"我希望这些命令和技巧可以帮助你找到桌面或服务器中问题/错误的根本原因。有关更多详细信息，你可以随时参考手册页并使用各种选项。如果你对本文有任何意见或想法，请使用下面的评论栏告诉我。",-1)),t[25]||(t[25]=s("p",null,"干杯。",-1)),t[26]||(t[26]=s("hr",null,null,-1)),s("p",null,[t[7]||(t[7]=a("via: ")),n(e,{href:"https://www.debugpoint.com/monitor-log-files-real-time/"},{default:l(()=>t[6]||(t[6]=[a("https://www.debugpoint.com/monitor-log-files-real-time/")])),_:1})]),s("p",null,[t[12]||(t[12]=a("作者：")),n(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:l(()=>t[8]||(t[8]=[a("Arindam")])),_:1}),t[13]||(t[13]=a(" 选题：")),n(e,{href:"https://github.com/lkxed"},{default:l(()=>t[9]||(t[9]=[a("lkxed")])),_:1}),t[14]||(t[14]=a(" 译者：")),n(e,{href:"https://github.com/geekpi"},{default:l(()=>t[10]||(t[10]=[a("geekpi")])),_:1}),t[15]||(t[15]=a(" 校对：")),n(e,{href:"https://github.com/wxy"},{default:l(()=>t[11]||(t[11]=[a("wxy")])),_:1})]),s("p",null,[t[18]||(t[18]=a("本文由 ")),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>t[16]||(t[16]=[a("LCTT")])),_:1}),t[19]||(t[19]=a(" 原创编译，")),n(e,{href:"https://linux.cn/"},{default:l(()=>t[17]||(t[17]=[a("Linux中国")])),_:1}),t[20]||(t[20]=a(" 荣誉推出"))])])}const y=o(r,[["render",g]]);export{k as __pageData,y as default};
